"""The wire list: parts with their pin-1 holes, then one table of wires per step."""

from __future__ import annotations

from .config import PerfboardConfig
from .grid import col_name, hole_name
from .route import bus_label

BANNER = (
    "<!-- Generated by tools/kicad (python3 -m kicad.perfboard) from hardware.toml; "
    "do not edit. -->"
)


def wire_list(parts, numbered, routes, cfg: PerfboardConfig, heavy):
    lines = [
        f"# {cfg.title} wire list",
        "",
        BANNER,
        "",
        f"Board: {cfg.cols} × {cfg.rows} holes, columns A–{col_name(cfg.cols - 1)}, rows 1–{cfg.rows}, "
        "named as seen from the **component side** (flip the drawing, not the names, on the solder side).",
        "Wires are numbered as in `perfboard.svg`, one drawing panel per step.",
        "Each wire's drawn route runs along the holes, over free ones only, or between "
        "them; its length is measured along that route.",
        f"A hole takes at most {cfg.conductors} conductors, a pin counting as one: a wire "
        "end goes through the hole beside the pin or another end, or is lapped on the pad. "
        "A *splice* is a free hole where wire ends of one net meet.",
        "A *bus* is bare tinned wire laid straight along its holes and soldered at every "
        "one; pads under it join it there.",
        f"Heavy nets ({cfg.heavy_label}) need {cfg.heavy_gauge} or heavier; "
        f"everything else {cfg.light_gauge}.",
        "Neighbouring holes (length 1) can be a solder bridge instead of a wire.",
        "",
        "## Parts",
        "",
        "| Ref | Part | Pin 1 at | Footprint |",
        "|---|---|---|---|",
    ]
    for p in sorted(parts.values(), key=lambda p: p.ref):
        lines.append(
            f"| {p.ref} | {p.value} | {hole_name(*p.pads['1'])} | `{p.fpid.split(':')[1]}` |"
        )
    for step, st in enumerate(cfg.steps):
        title, subtitle = st.title, st.subtitle
        lines += [
            "",
            f"## Step {step + 1}: {title}",
            "",
            f"{subtitle[0].upper()}{subtitle[1:]}.",
            "",
            "| ✓ | # | Net | Gauge | From | To | Length (holes) |",
            "|---|---|---|---|---|---|---|",
        ]
        for row in step_rows(numbered, routes, cfg, heavy, step):
            lines.append("| ☐ | " + " | ".join(map(str, row)) + " |")
    return "\n".join(lines) + "\n"


def step_rows(numbered, routes, cfg: PerfboardConfig, heavy, step):
    """Step `step`'s wires: (number, net, gauge, from, to, length in holes)."""
    for n, st_, net, _, (ha, la), (hb, lb) in numbered:
        if st_ != step:
            continue
        length = (len(routes[n]) - 1) / 2  # half-pitch steps to holes
        gauge = cfg.heavy_gauge if net in heavy else cfg.light_gauge
        if la == lb == bus_label(net):
            gauge = f"bare, {gauge}"
        yield (
            n,
            net,
            gauge,
            f"{la} ({hole_name(*ha)})",
            f"{lb} ({hole_name(*hb)})",
            f"{length:g}",
        )
